test('should list pinned discussions first with a pinned badge', async () => {
  const fakeUser = await createUser();
  const regular = await createDiscussionInDb({
    teamId: fakeUser.teamId,
    title: 'Regular discussion',
  });
  const pinned = await createDiscussionInDb({
    teamId: fakeUser.teamId,
    title: 'Pinned discussion',
    pinned: true,
  });

  await renderApp(<DiscussionsRoute />, { user: fakeUser });

  await screen.findByText(regular.title);

  const [, firstRow, secondRow] = screen.getAllByRole('row');

  expect(within(firstRow).getByText(pinned.title)).toBeInTheDocument();
  expect(within(firstRow).getByText(/^pinned$/i)).toBeInTheDocument();
  expect(within(secondRow).getByText(regular.title)).toBeInTheDocument();
  expect(within(secondRow).queryByText(/^pinned$/i)).not.toBeInTheDocument();
});
EOF
